CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE holdings (symbol TEXT NOT NULL, exchange TEXT NOT NULL CHECK(exchange IN ('NSE','BSE')), quantity REAL NOT NULL CHECK(quantity>0), average_price REAL NOT NULL CHECK(average_price>0), sector TEXT NOT NULL, source TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(symbol,exchange));
CREATE TABLE quotes (symbol TEXT NOT NULL, exchange TEXT NOT NULL, payload TEXT NOT NULL, fetched_at TEXT NOT NULL, PRIMARY KEY(symbol,exchange));
CREATE TABLE watchlist (symbol TEXT NOT NULL, exchange TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(symbol,exchange));
CREATE TABLE articles (id TEXT PRIMARY KEY, canonical_url TEXT UNIQUE NOT NULL, title TEXT NOT NULL, source TEXT NOT NULL, kind TEXT NOT NULL, published_at TEXT NOT NULL, fetched_at TEXT NOT NULL, summary TEXT NOT NULL, symbols TEXT NOT NULL, sentiment REAL NOT NULL);
CREATE INDEX articles_published ON articles(published_at DESC);
CREATE VIRTUAL TABLE articles_fts USING fts5(title,summary,content='articles',content_rowid='rowid');
CREATE TRIGGER articles_insert AFTER INSERT ON articles BEGIN INSERT INTO articles_fts(rowid,title,summary) VALUES(new.rowid,new.title,new.summary); END;
CREATE TRIGGER articles_delete AFTER DELETE ON articles BEGIN INSERT INTO articles_fts(articles_fts,rowid,title,summary) VALUES('delete',old.rowid,old.title,old.summary); END;
CREATE TABLE bookmarks (article_id TEXT PRIMARY KEY REFERENCES articles(id) ON DELETE CASCADE, created_at TEXT NOT NULL);
CREATE TABLE notes (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, thesis TEXT NOT NULL, risk TEXT NOT NULL, catalyst TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE alerts (id TEXT PRIMARY KEY, symbol TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('above','below')), target REAL NOT NULL CHECK(target>0), triggered_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE ipo_snapshots (slug TEXT NOT NULL, observed_at TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(slug,observed_at));
CREATE INDEX ipo_latest ON ipo_snapshots(slug,observed_at DESC);
CREATE TABLE jobs (id TEXT PRIMARY KEY, provider TEXT NOT NULL, status TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, message TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE cache (key TEXT PRIMARY KEY, payload TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE broker_session (id INTEGER PRIMARY KEY CHECK(id=1), encrypted_token TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, session_hash TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
